create table wksp_dtesc.sgt_cat_tipo_activo_evento (
    id               number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    codigo           varchar2(30 byte) not null enable,
    nombre           varchar2(100 byte) not null enable,
    tabla_objetivo   varchar2(100 byte) not null enable,
    pk_columna       varchar2(100 byte) not null enable,
    etiqueta_columna varchar2(100 byte),
    activo           varchar2(1 byte) default 'Y' not null enable,
    creado_por       varchar2(255 byte),
    creado_el        timestamp(6) default systimestamp
);

alter table wksp_dtesc.sgt_cat_tipo_activo_evento
    add constraint chk_sgt_cat_tipo_activo_evento_activo
        check ( activo in ( 'Y', 'N' ) ) enable;

alter table wksp_dtesc.sgt_cat_tipo_activo_evento
    add constraint pk_sgt_cat_tipo_activo_evento primary key ( id )
        using index enable;

alter table wksp_dtesc.sgt_cat_tipo_activo_evento add constraint uq_sgt_cat_tipo_activo_evento_codigo unique ( codigo )
    using index enable;


